static NSDictionary *PVXPlist(NSString *path){struct stat st;if(lstat(path.fileSystemRepresentation,&st)||!S_ISREG(st.st_mode)||st.st_size<8||st.st_size>2*1024*1024)return nil;NSData *d=[NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:nil];if(!d)return nil;id v=[NSPropertyListSerialization propertyListWithData:d options:NSPropertyListImmutable format:NULL error:nil];return [v isKindOfClass:NSDictionary.class]?v:nil;}
