NSArray<NSDictionary*> *PVXReadVideoTasks(void){NSString *root=PVXStateRoot();if(!root.length)return @[];NSMutableArray *rows=[NSMutableArray array];for(NSString *sub in @[@"tasks",@"image-tasks"]){NSString *dir=[root stringByAppendingPathComponent:sub];NSUInteger count=0;for(NSString *file in [NSFileManager.defaultManager contentsOfDirectoryAtPath:dir error:nil]){if(![file.pathExtension isEqual:@"plist"]||!PVXUUID(file.stringByDeletingPathExtension))continue;NSDictionary *raw=PVXPlist([dir stringByAppendingPathComponent:file]);if(!raw||![raw[@"id"] isEqual:file.stringByDeletingPathExtension])continue;if([raw[@"state"] isEqual:@"deleted"])continue;NSMutableDictionary *row=[raw mutableCopy];[row removeObjectForKey:@"headers"];[row removeObjectForKey:@"cookies"];row[@"kind"]=[sub isEqual:@"image-tasks"]?@"image":@"video";row[@"title"]=PVXSafeText(raw[@"title"],180);if(![row[@"created"] isKindOfClass:NSNumber.class])row[@"created"]=@0;[rows addObject:row];if(++count>=500)break;}}
[rows sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){NSComparisonResult r=[b[@"created"] compare:a[@"created"]];return r==NSOrderedSame?[a[@"id"] compare:b[@"id"]]:r;}];return rows;}
BOOL PVXAutoSavePhotos(void){id v=PVXPlist([PVXStateRoot() stringByAppendingPathComponent:@"plus-preferences.plist"])[@"autoSavePhotos"];return [v isKindOfClass:NSNumber.class]?[v boolValue]:YES;}
