static NSString *PVXLocalFile(NSDictionary *task){NSString *uuid=task[@"id"];if(!PVXUUID(uuid))return nil;NSString *root=PVXStateRoot();BOOL image=[task[@"kind"] isEqual:@"image"];NSArray *paths=image?@[[root stringByAppendingPathComponent:[@"image-media/" stringByAppendingFormat:@"%@.original",uuid]]]:@[[root stringByAppendingPathComponent:[@"retained/" stringByAppendingFormat:@"%@.mp4",uuid]],[root stringByAppendingPathComponent:[@"media/" stringByAppendingFormat:@"%@.mp4.compatible.mp4",uuid]],[root stringByAppendingPathComponent:[@"media/" stringByAppendingFormat:@"%@.mp4",uuid]]];NSSet *complete=[NSSet setWithArray:@[@"ready",@"saved",@"albumFailed",@"uncertain"]];if(![complete containsObject:task[@"state"]]&&![task[@"fileComplete"] boolValue])return nil;for(NSString *p in paths){struct stat st;if(!lstat(p.fileSystemRepresentation,&st)&&S_ISREG(st.st_mode)&&st.st_size>0)return p;}return nil;}
BOOL PVXTaskHasLocalFile(NSDictionary *task){return PVXLocalFile(task)!=nil;}
void PVXTaskAction(NSDictionary *task,NSString *action){if(!PVXUUID(task[@"id"]))return;if([task[@"kind"] isEqual:@"image"]){PVXAlert(@"图片任务",@"本轮图片任务可保存到相册或文件；活动任务操作请等待下载完成。");return;}typedef BOOL(*Control)(id,id,NSError**);Control fn=(Control)dlsym(RTLD_DEFAULT,"PVEnqueueControl");if(!fn){PVXAlert(@"任务操作失败",@"原下载服务接口尚未加载");return;}NSError *err=nil;if(!fn(task[@"id"],action,&err))PVXAlert(@"任务操作失败",err.localizedDescription?:@"请求未写入");}
void PVXSaveTaskToPhotos(NSDictionary *task){if(!PVXUUID(task[@"id"])||!PVXTaskHasLocalFile(task)){PVXAlert(@"尚无可保存文件",@"请等待下载完成。");return;}if([task[@"state"] isEqual:@"saved"]){PVXAlert(@"已保存相册",@"这项任务已完成相册保存，无需重复写入。");return;}if([task[@"state"] isEqual:@"uncertain"]){PVXAlert(@"先检查相册",@"上次相册事务结果待确认，不会自动重复保存；本地文件仍可导出到“文件”。");return;}if(![task[@"kind"] isEqual:@"image"]&&![task[@"state"] isEqual:@"ready"]){PVXAlert(@"任务尚未准备保存",@"相册失败任务请先使用“重试”，再选择保存到相册。");return;}void(^submit)(void)=^{NSString *dir=[task[@"kind"] isEqual:@"image"]?@"plus-image-photos":@"plus-manual-photos";NSString *file=[[PVXStateRoot() stringByAppendingPathComponent:dir] stringByAppendingPathComponent:[task[@"id"] stringByAppendingPathExtension:@"plist"]];NSError *err=nil;if(!PVXAtomic(@{@"id":task[@"id"],@"created":@(NSDate.date.timeIntervalSince1970)},file,&err)){PVXAlert(@"相册请求失败",err.localizedDescription?:@"无法写入请求");return;}notify_post([task[@"kind"] isEqual:@"image"]?"com.crctdd.pyvideo.plus.images.queue":"com.crctdd.pyvideo.plus.storage");};submit();}

