static long long PVXBytes(id v){return [v isKindOfClass:NSNumber.class]?MAX(0,[v longLongValue]):0;}
NSDictionary *PVXTaskPresentation(NSDictionary *task){NSString *state=PVXSafeText(task[@"state"],40);BOOL image=[task[@"kind"] isEqual:@"image"];NSDictionary *names=@{@"queued":@"等待下载",@"downloading":@"下载中",@"hls":@"下载中",@"remuxing":@"正在封装",@"checking":@"校验中",@"converting":@"转换中",@"ready":@"下载成功",@"saved":@"下载成功",@"saving":@"正在保存相册",@"albumFailed":@"已下载 · 相册保存失败",@"failed":@"下载失败",@"pausing":@"正在暂停",@"paused":@"已暂停",@"uncertain":@"已下载 · 相册结果待确认",@"deleting":@"正在删除"};NSString *status=names[state]?:@"等待处理";BOOL success=[@[@"ready",@"saved",@"albumFailed",@"uncertain"] containsObject:state];BOOL fail=[state isEqual:@"failed"];UIColor *tint=success?UIColor.systemGreenColor:fail?UIColor.systemRedColor:UIColor.systemBlueColor;NSString *symbol=success?@"checkmark.circle.fill":fail?@"exclamationmark.circle.fill":[state isEqual:@"paused"]?@"pause.circle.fill":@"arrow.down.circle.fill";long long received=PVXBytes(task[@"received"]),total=PVXBytes(task[@"total"]);if(success&&!received){NSString *f=PVXLocalFile(task);struct stat st;if(f&&!lstat(f.fileSystemRepresentation,&st))received=st.st_size;}double progress=total>0?MIN(1.,(double)received/total):0;NSString *size=[NSByteCountFormatter stringFromByteCount:received countStyle:NSByteCountFormatterCountStyleDecimal];if(total>0&&!success)size=[NSString stringWithFormat:@"%@/%@ (%.1f%%)",size,[NSByteCountFormatter stringFromByteCount:total countStyle:NSByteCountFormatterCountStyleDecimal],progress*100];long long seg=PVXBytes(task[@"segmentsDone"]),segTotal=PVXBytes(task[@"segmentsTotal"]);if(segTotal>0&&!success){progress=MIN(1.,(double)seg/segTotal);size=[NSString stringWithFormat:@"%@ · %lld/%lld 片 (%.1f%%)",size,seg,segTotal,progress*100];}if([state isEqual:@"converting"]&&[task[@"conversionProgress"] isKindOfClass:NSNumber.class]){progress=MIN(1.,MAX(0.,[task[@"conversionProgress"] doubleValue]));size=[NSString stringWithFormat:@"%@ · 转换 %.1f%%",size,progress*100];}NSString *format=image?PVXSafeText(task[@"uti"],64):@"mp4";if